"""Generate a ROM from synthetic glyphs only; never train on user frames."""
from pathlib import Path
import hashlib
from prototype_digit_v106 import templates,GLYPHS
ROOT=Path(__file__).resolve().parents[1]
def main():
 table=templates();lines=[]
 for digit,patterns in enumerate(table):
  words=[''.join(map(str,p.ravel())) for p in patterns]
  canonical=GLYPHS[digit].replace('/','')
  assert len(words)<=64
  words+=[canonical]*(64-len(words))
  for variant,word in enumerate(words):lines.append(f"  rom[{digit*64+variant}]=35'b{word};")
 text='''`timescale 1ns/1ps
// Generated by tools/generate_digit_templates_v106.py.
// 64 synthetic size/tilt/aspect variants per digit, not camera frames.
module ua_digit_template_rom(input I_clk,input[9:0]I_address,output reg[34:0]O_bits);
 /* fehdl force_ram=1, ram_style="bram" */ reg[34:0]rom[0:1023];
 integer i;
 initial begin
'''+ '\n'.join(lines)+'''
  for(i=640;i<1024;i=i+1)rom[i]=35'd0;
 end
 always @(posedge I_clk)O_bits<=rom[I_address];
endmodule
'''
 p=ROOT/'rtl/user/ua_digit_template_rom.v';p.write_text(text,encoding='utf-8')
 print('DIGIT_V106_SYNTHETIC_CODEBOOK',list(map(len,table)),hashlib.sha256(p.read_bytes()).hexdigest())
if __name__=='__main__':main()
